// === Tab: mySketch ===
class Mariposa {
  constructor(cx, cy, size = 1, lineMode = false) {
    this.cx = cx;
    this.cy = cy;
    this.size = size;
    this.lineMode = lineMode;

    this.a = 9;
    this.b = 28;
    this.c = 2;

    this.timeStep = 0.005;
    this.numIterations = 5000;
    this.minDist = 2;
    this.time = 0;

    this.p1 = createVector(cx, cy);
    this.p2 = this.randomPoint();
    this.p3 = this.randomPoint();
    this.t = 0;
    this.speed = 0.002 + random(0.0015);
    this.angle = 0;
    this.progressEpsilon = 10;

    // control del fade
    this.opacity = 255;
    this.fadeSpeed = 10;
    this.fadingOut = false;
    this.fadingIn = true;

    // 💡 Variaciones individuales del aleteo
    this.VelAleteo = random(0.6, 1.8);   // velocidad del batir de alas
    this.freqAleteo = random(70, 130);   // frecuencia del patrón senoidal
  }

  randomPoint() {
    return createVector(random(width), random(height));
  }

  update() {
    this.time += this.VelAleteo;
    this.t += this.speed;
    if (this.t > 1) this.t = 1;

    const pos = this.bezierPointVec(this.p1, this.p2, this.p3, this.t);
    this.cx = pos.x;
    this.cy = pos.y;

    const lookT = min(1, this.t + max(0.01, this.speed * 3));
    const look = this.bezierPointVec(this.p1, this.p2, this.p3, lookT);
    this.angle = atan2(look.y - pos.y, look.x - pos.x);

    // Fade in / out
    if (this.fadingIn) {
      this.opacity += this.fadeSpeed;
      if (this.opacity >= 255) {
        this.opacity = 255;
        this.fadingIn = false;
      }
    } else if (this.fadingOut) {
      this.opacity -= this.fadeSpeed;
      if (this.opacity <= 0) {
        this.opacity = 0;
        this.fadingOut = false;
        this.p1 = this.p3.copy();
        this.p2 = this.randomPoint();
        this.p3 = this.randomPoint();
        this.t = 0;
        this.fadingIn = true;
      }
    }

    // Inicia fade-out cerca del final
    const distToP3 = p5.Vector.dist(pos, this.p3);
    if (!this.fadingOut && distToP3 < this.progressEpsilon * 5) {
      this.fadingOut = true;
    }
  }

  bezierPointVec(p1, p2, p3, t) {
    const x = (1 - t) ** 2 * p1.x + 2 * (1 - t) * t * p2.x + t ** 2 * p3.x;
    const y = (1 - t) ** 2 * p1.y + 2 * (1 - t) * t * p2.y + t ** 2 * p3.y;
    return createVector(x, y);
  }

  draw() {
    push();
    translate(this.cx, this.cy);
    rotate(this.angle + PI / 2);
    scale(this.size);
    stroke(255, this.opacity);
    noFill();
    beginShape();

    var x = 0.1, y = 0.1, z = 0.1;
    let lastX = NaN, lastY = NaN;
    const minDistSq = this.minDist * this.minDist;

    for (let i = 0; i < this.numIterations; i++) {
      // 💫 cada mariposa tiene su propia frecuencia de "aleteo"
      const swirl = sin(this.time * PI / this.freqAleteo + z / 49 + x * x / 400);
      const sx = (x + y) * (swirl * 2 + 2);
      const sy = -z * 5;

      if (i === 0) {
        vertex(sx, sy);
        lastX = sx;
        lastY = sy;
      } else {
        const dx = sx - lastX;
        const dy = sy - lastY;
        if (dx * dx + dy * dy > minDistSq) {
          vertex(sx, sy);
          lastX = sx;
          lastY = sy;
        }
      }

      var dx = this.a * (y - x);
      var dy = x * (this.b - z) - y;
      const dz = x * y - this.c * z;
      x += dx * this.timeStep;
      y += dy * this.timeStep;
      z += dz * this.timeStep;
    }

    endShape();
    pop();
  }
}

// --- Sketch principal ---
let mariposas = [];

function setup() {
  createCanvas(windowWidth, windowHeight);
  noFill();
  strokeWeight(0.7);

  // 🔹 Crear 4 mariposas con parámetros independientes
  for (let i = 0; i < 4; i++) {
    mariposas.push(
      new Mariposa(
        random(width),
        random(height),
        max(width, height) * 0.001,
        true
      )
    );
  }
}

function draw() {
  background(11);
  for (let m of mariposas) {
    m.update();
    m.draw();
  }
}

function windowResized() {
  resizeCanvas(windowWidth, windowHeight);
}

